154	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
155	      // below restores all three. The scratch is vlenb-packed
156	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
157	      if (scratch_gpa_ == kVScratchGpaUnset)
158	        throw std::runtime_error(
159	          "ResumeDriver::resume: V state present but scratch GPA unset");
