217	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
218	  // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
219	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
220	  //
221	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
222	  // mode) and the ELF scan is skipped: the binary need not contain a magic
223	  // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
224	  // run -- callers pass exactly one form.
225	  void enable_hybrid_handoff(const std::string& elf_path,
226	                             const std::string& state_out_path,
227	                             std::optional<uint64_t> exit_pc = std::nullopt,
228	                             bool drain_minimal = false)
229	  {
230	    hybrid::CsrTrigger trigger;
231	    if (exit_pc) {
232	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
233	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
234	    } else {
235	      auto elf = LIEF::ELF::Parser::parse(elf_path);
236	      if (!elf)
237	        throw std::runtime_error(
238	          "enable_hybrid_handoff: failed to parse " + elf_path);
239	      for (const auto& seg: elf->segments()) {
240	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
241	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
242	        const auto content = seg.content();
243	        const std::span<const uint8_t> bytes{content.data(), content.size()};
244	        trigger.scan_buffer(bytes, seg.virtual_address());
245	      }
246	    }
247	
248	    hybrid_dmi_bus_ = std::make_unique<
249	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
250	                            PLATFORM::dmi_data_width>>(platform.dmi,
251	                                                       platform.clk.period());
252	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
253	                            v_scratch_gpa(), hybrid::andes_caps_from_config());
254	    if (hybrid_input_state_)
255	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
256	    hybrid_handoff_->set_minimal_drain(drain_minimal);
257	    hybrid_state_path_ = state_out_path;
258	  }
259	
260	private:
261	  // L26: the GUEST address of the V-register transport page -- the top page of
262	  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
263	  // so this sits just past the program's declared RAM and never collides with
264	  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.

