// GPR block-load (prototype): seed x31 with the scratch GPA, then ld x1..x31
// from their slots via the Program Buffer. x31 (the base) is loaded LAST so it
// stays valid through the earlier loads; the 15-slot buffer holds 15 loads per
// execution, so 31 registers take 1 abstract write + 3 PB executions instead
// of 31 abstract writes. `ld`'s 12-bit offset spans all 31 slots (<= 240).
void restore_gprs_via_pb(uint64_t gpr_gpa)
{
  // The Program Buffer holds abstractcs.progbufsize entries (this DM reports
  // 8); reserve one slot for the terminating ebreak, so at most
  // progbufsize-1 loads per execution. x31 is the base and is loaded LAST, so
  // it stays valid through the earlier loads even across executions.
  const uint32_t progbufsize = (bus_.read(kAbstractcs) >> 24) & 0x1Fu;
  const std::size_t max_lds = (progbufsize > 1) ? progbufsize - 1u : 1u;
  write_register_abstract(bus_, regno_gpr(31), gpr_gpa);  // base pointer

