  // (a) all 31 registers are reloaded via ld in the Program Buffer.
  int found = 0;
  for (uint8_t k = 1; k < 32; ++k)
    if (in_progbuf(hybrid::encode_ld(k, 31, static_cast<int32_t>((k - 1) * 8))))
      ++found;
  CHECK(found == 31);

  // (b) the ONLY GPR abstract write is x31 seeded with the scratch GPA (the
  //     base pointer); x1..x30 come via ld, not per-register abstract writes.
  const uint64_t gpr_gpa = hybrid::gpr_scratch_gpa(kScratch);
  int gpr_abstract_writes = 0;
  bool base_is_gpr_gpa = false;
  for (std::size_t i = 0; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    const uint16_t rn = static_cast<uint16_t>(op.value & 0xFFFFu);
    if (rn >= hybrid::regno_gpr(1) && rn <= hybrid::regno_gpr(31)
        && ((op.value >> 16) & 1u)) {
      ++gpr_abstract_writes;
      if (rn == hybrid::regno_gpr(31) && i >= 2)
        base_is_gpr_gpa =
          bus.ops[i - 2].reg == kData0
          && bus.ops[i - 2].value == uint32_t(gpr_gpa & 0xffffffffu)
          && bus.ops[i - 1].reg == kData1
          && bus.ops[i - 1].value == uint32_t(gpr_gpa >> 32);
    }
  }
  CHECK(gpr_abstract_writes == 1);
  CHECK(base_is_gpr_gpa);

  // (c) with progbufsize=8 (7 loads/execution) the sweep is 5 Program-Buffer
  //     executions (7+7+7+7+3), not 31 abstract writes.
  int execs = 0;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && op.value == hybrid::kExecProgbufCmd)
      ++execs;
  CHECK(execs == 5);
}

