// GPR block-load (prototype): seed x31 with the scratch GPA, then ld x1..x30
// from their slots via the Program Buffer, and finally restore x31 (the base)
// with one abstract write. So 31 registers cost 2 abstract writes + a few PB
// executions instead of 31 abstract writes. `ld`'s 12-bit offset spans all
// slots (<= 232). x31's own slot (the mmap's final word) is left as a guard
// because the guest RTL does not return the last word of the shared mapping.
void restore_gprs_via_pb(uint64_t gpr_gpa, uint64_t gpr31_value)
{
  // The Program Buffer holds abstractcs.progbufsize entries (this DM reports
  // 8); reserve one slot for the terminating ebreak, so at most
  // progbufsize-1 loads per execution. x31 stays the base through every
  // load (it is never overwritten by an ld), so batches compose freely.
  const uint32_t progbufsize = (bus_.read(kAbstractcs) >> 24) & 0x1Fu;
  const std::size_t max_lds = (progbufsize > 1) ? progbufsize - 1u : 1u;
  write_register_abstract(bus_, regno_gpr(31), gpr_gpa);  // base pointer
  std::array<uint32_t, 32> batch{};
  std::size_t n = 0;
  for (uint8_t k = 1; k < 31; ++k) {  // x1..x30 (x31 restored below)
    batch[n++] = encode_ld(k, 31, static_cast<int32_t>((k - 1) * 8));
    if (n == max_lds || k == 30) {
      exec_progbuf(bus_, std::span<const uint32_t>{batch.data(), n});
      n = 0;
    }
  }
  // x31 is the base pointer and its scratch slot is the guard word the guest
  // cannot read, so restore it directly with one abstract write (not an ld).
  write_register_abstract(bus_, regno_gpr(31), gpr31_value);
}

