  //     (x5 is later overwritten by the abstract GPR loop -- both writes exist;
  //     this checks the seed value is present.)
  const uint64_t fpr_gpa = hybrid::fpr_scratch_gpa(kScratch);
  bool base_seed_found = false;
  for (std::size_t i = 2; i < bus.ops.size(); ++i) {
    const auto& op = bus.ops[i];
    if (op.kind != DmiOp::Kind::Write || op.reg != kCommand) continue;
    if (!((op.value >> 16) & 1u)) continue;  // write bit
    if (static_cast<uint16_t>(op.value & 0xFFFFu) != hybrid::regno_gpr(5))
      continue;
    const uint64_t v =
        (uint64_t(bus.ops[i - 1].value) << 32) | bus.ops[i - 2].value;
    if (v == fpr_gpa) base_seed_found = true;
  }
  CHECK(base_seed_found);

  // (d) with progbufsize=8 (7 loads/execution) the 32 loads take 5 Program-
  //     Buffer executions (7+7+7+7+4), not 32 abstract writes.
  int execs = 0;
  for (const auto& op : bus.ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == kCommand
        && op.value == hybrid::kExecProgbufCmd)
      ++execs;
  CHECK(execs == 5);
}

