115	  void resume(const hybrid_state_v1& state)
116	  {
117	    if (state.magic != HYBRID_STATE_MAGIC)
118	      throw std::runtime_error("ResumeDriver::resume: bad magic");
119	    if (state.version != HYBRID_STATE_VERSION)
120	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
121	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
122	    if (state.priv == 2 || state.priv > 3)
123	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
124	
125	    // dmactive must transition 0->1 in its own write before any other
126	    // DMCONTROL bit is honored (RISC-V Debug Spec).
127	    bus_.write(kDmcontrol, kDmcontrolDmactive);
128	    request_halt();
129	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
130	
131	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
132	    // accepted (FS or VS == Off disables the extension and the hart NACKs
133	    // the writes). The drained state.mstatus may legitimately carry FS or
134	    // VS at Off (e.g. an OS context-switched the regs away before the
135	    // trigger fired) -- gating the write on the drained field skips the
136	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
137	    // write mstatus when either extension is in scope; force-OR Initial
138	    // when the drained field is Off. This enable is local to the vsim
139	    // phase; the state.mstatus written to the handoff file is left
140	    // unmodified.
141	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
142	      uint64_t enable_mstatus = state.mstatus;
143	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
144	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
145	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
146	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
147	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
148	    }
149	
150	    // FPR restore (requires mstatus.FS enabled above). The block-load (opt-in)
151	    // sweeps f0..f31 from the scratch page via a PB fld-sweep -- ~6 halted-hart
152	    // round-trips instead of 32 abstract writes -- when the V region leaves room;
153	    // otherwise fall back to per-register abstract writes. Its integer base x5 is
154	    // re-staged by the V sweep and restored by the GPR loop below, so it is safe
155	    // to clobber here.
156	    if (state.flags & HYBRID_FLAG_FP) {
157	      if (fpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
158	          && fpr_scratch_fits(state.vlenb)) {
159	        restore_fprs_via_pb(fpr_scratch_gpa(scratch_gpa_));
160	      } else {
161	        for (uint16_t i = 0; i < 32; ++i)
162	          write_64bit_register(regno_fpr(i), state.fpr[i]);
163	      }
164	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
165	      // fallback scratch x5 is overwritten by the GPR loop below.
166	      write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
167	    }
168	
169	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
170	    // the GPR loop overwrites x5 afterward so state is preserved).
171	    if (state.flags & HYBRID_FLAG_V) {
172	      // V data regfile: reload v0..v31 from the shared scratch region via the
173	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
174	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
175	      // the restore then overwrites with the architectural values. The sweep
176	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
177	      // below restores all three. The scratch is vlenb-packed
178	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
179	      if (scratch_gpa_ == kVScratchGpaUnset)
180	        throw std::runtime_error(
181	          "ResumeDriver::resume: V state present but scratch GPA unset");
182	      pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
183	
184	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
185	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
186	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
187	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
188	      write_64bit_register(regno_gpr(5), state.vl);
189	      write_64bit_register(regno_gpr(6), state.vtype);
190	      const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
191	      exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
192	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0.
193	      write_csr_abstract_or_pb(kCsrVstart, state.vstart);
194	      write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
195	      write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
196	      write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
197	    }
198	
199	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
200	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
201	    // in the drained privilege; M-mode states skip the write (prv already 3).
202	    // Before the GPR loop: a PB fallback would clobber scratch x5.
203	    if (state.priv != 3) {
204	      // L2 slice: with PMP implemented and no matching entry, every S/U
205	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
206	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
207	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
208	      // RV64. Tolerant writes: entries beyond what the hart implements
209	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
210	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
211	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
212	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
213	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
214	
215	      const uint64_t dcsr =
216	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
217	      write_csr_abstract_or_pb(kCsrDcsr,
218	                               (dcsr & ~uint64_t{0x3}) | state.priv);
219	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
220	      // silently measure the ROI in the wrong privilege. Verify and abort.
221	      const uint64_t got =
222	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
223	        & 0x3u;
224	      if (got != state.priv)
225	        throw std::runtime_error(
226	          "ResumeDriver::resume: engine does not implement privilege level "
227	          + std::to_string(state.priv)
228	          + " (dcsr.prv pinned to " + std::to_string(got)
229	          + "); pick an S/U-capable engine");
230	    }
231	
232	    // GPRs + DPC (after V CSRs so PB scratch x5 is safe to overwrite). The
233	    // block-load (opt-in) sweeps x1..x31 from the scratch page via the Program
234	    // Buffer -- ~4 DM round-trips instead of 31 abstract writes -- when the V
235	    // region leaves room; otherwise fall back to per-register abstract writes.
236	    if (gpr_block_load_ && scratch_gpa_ != kVScratchGpaUnset
237	        && gpr_scratch_fits(state.vlenb)) {
238	      restore_gprs_via_pb(gpr_scratch_gpa(scratch_gpa_));
239	    } else {
240	      for (uint16_t i = 1; i < 32; ++i)
241	        write_64bit_register(regno_gpr(i), state.gpr[i]);
242	    }
243	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
244

