597	  HYBRID_ANDES_CSR_LIST(X)
598	#undef X
599	  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
600	    CHECK(state.andes.pmacfg[i] == uint64_t(0x800 + i));
601	  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
602	    CHECK(state.andes.pmaaddr[i] == uint64_t(0x900 + i));
603	}
604	
605	TEST_CASE("Andes caps: drain_with_passthrough skips re-reading the CSRs the "
606	          "core lacks (no hang), keeps their passthrough, re-reads the rest")
607	{
608	  RecordingBus bus;
609	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
610	  bus.regfile[hybrid::regno_csr(0x800)] = 0xABCDEULL;  // uitb  (supported)
611	  bus.regfile[hybrid::regno_csr(0x7C0)] = 0x12345ULL;  // milmb (supported)
612	  bus.regfile[hybrid::regno_csr(0x801)] = 0x999ULL;    // ucode (absent; must NOT be read)
613	
614	  hybrid_state_v1 input{};
615	  input.magic   = HYBRID_STATE_MAGIC;
616	  input.version = HYBRID_STATE_VERSION;
617	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES;
618	  input.priv    = 3;
619	  input.andes.ucode     = 0xDEAD;
620	  input.andes.mecc_code = 0xDEAD;
621	  input.andes.uitb      = 0xBEEF;  // stale; must be overwritten by the re-read
622	
623	  // ax45mpv_premium: CoDense + ILM + DLM only.
624	  hybrid::AndesCaps premium = hybrid::AndesCaps::none();
625	  premium.set(hybrid::AndesGate::CODENSE);
626	  premium.set(hybrid::AndesGate::ILM);
627	  premium.set(hybrid::AndesGate::DLM);
628	
629	  hybrid::StateDrain drain(bus, kScratch, premium);
630	  const auto state = drain.drain_with_passthrough(input);
631	
632	  // Supported -> re-read from the hart.
633	  CHECK(state.andes.uitb  == 0xABCDEULL);
634	  CHECK(state.andes.milmb == 0x12345ULL);
635	  // Absent -> NOT re-read: passthrough value kept, and no read-COMMAND issued
636	  // (anti-hang, symmetric with the restore gate).
637	  CHECK(state.andes.ucode     == 0xDEADULL);
638	  CHECK(state.andes.mecc_code == 0xDEADULL);
639	  for (const auto& op : bus.ops) {
640	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
641	    CHECK((op.value & 0xFFFFu) != hybrid::regno_csr(0x801));  // ucode
642	    CHECK((op.value & 0xFFFFu) != hybrid::regno_csr(0x7C2));  // mecc_code
643	  }
644	}
645	
646	TEST_CASE("Andes v3: drain_with_passthrough without HYBRID_FLAG_ANDES leaves the "
647	          "Andes block as the passthrough snapshot (no re-read)")
648	{
649	  RecordingBus bus;
650	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
651	  bus.regfile[hybrid::regno_csr(0x7C4)]  = 0x1234;  // mxstatus live in the hart
652	  bus.regfile[hybrid::regno_csr(0xBD0)]  = 0x5678;  // pmaaddr0 live in the hart
653	
654	  hybrid_state_v1 input{};
655	  input.magic   = HYBRID_STATE_MAGIC;
656	  input.version = HYBRID_STATE_VERSION;
657	  input.flags   = HYBRID_FLAG_RV64;  // ANDES not set
658	  input.priv    = 3;
659	  input.andes.mxstatus  = 0xCAFE;
660	  input.andes.pmaaddr[0] = 0xF00D;
661	
662	  hybrid::StateDrain drain(bus, kScratch);
663	  const auto state = drain.drain_with_passthrough(input);
664	
665	  CHECK(state.andes.mxstatus  == 0xCAFE);  // passthrough preserved, not re-read
666	  CHECK(state.andes.pmaaddr[0] == 0xF00D);
667	}
668	
669	// #1 (drain-minimal): when --verify is off the driver consumes only the vsim
670	// mcycle delta, so the full register-file readback (~190 DMI abstract commands)
671	// is wasted. drain_counters_only refreshes mcycle+minstret from the hart and
672	// passes every other field through from the QEMU1 snapshot, issuing exactly two
673	// abstract-command reads.
674	TEST_CASE("drain_counters_only refreshes only mcycle+minstret, preserves passthrough")
675	{
676	  RecordingBus bus;
677	  bus.dmstatus_value = kDmstatusHaltedAndAcked;
678	  bus.regfile[hybrid::regno_csr(RD::kCsrMcycle)]   = 0xABCD1234ULL;
679	  bus.regfile[hybrid::regno_csr(RD::kCsrMinstret)] = 0x56789ABCULL;
680	
681	  // Passthrough input (QEMU1 snapshot) with distinctive non-counter fields.
682	  hybrid_state_v1 input{};
683	  input.magic   = HYBRID_STATE_MAGIC;
684	  input.version = HYBRID_STATE_VERSION;
685	  input.flags   = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP | HYBRID_FLAG_V
686	                  | HYBRID_FLAG_ANDES | HYBRID_FLAG_M_EXT;
687	  input.priv    = 3;
688	  for (uint16_t i = 0; i < 32; ++i) {
689	    input.gpr[i] = 0x1000ULL + i;
690	    input.fpr[i] = 0x2000ULL + i;
691	  }
692	  input.mstatus        = 0xDEADULL;
693	  input.andes.mxstatus = 0xBEEFULL;
694	  input.m_ext.menvcfg  = 0xCAFEULL;
695	  input.mcycle = input.minstret = 0;  // stale -- must be overwritten by the read
696	
697	  hybrid::StateDrain drain(bus, kScratch);
698	  const auto out = drain.drain_counters_only(input);
699	
700	  // Counters refreshed from the hart.
701	  CHECK(out.mcycle   == 0xABCD1234ULL);
702	  CHECK(out.minstret == 0x56789ABCULL);
703	  // Every other field passes through untouched (no DMI read issued for it).
704	  CHECK(out.mstatus        == 0xDEADULL);
705	  CHECK(out.andes.mxstatus == 0xBEEFULL);
706	  CHECK(out.m_ext.menvcfg  == 0xCAFEULL);
707	  for (uint16_t i = 1; i < 32; ++i) {
708	    CHECK(out.gpr[i] == 0x1000ULL + i);
709	    CHECK(out.fpr[i] == 0x2000ULL + i);
710	  }
711	
712	  // The whole point of #1: the ONLY abstract-command reads are the two
713	  // counters -- no GPR/FPR/CSR register-file readback.
714	  int reads = 0, mcycle_reads = 0, minstret_reads = 0;
715	  for (const auto& op : bus.ops) {
716	    if (op.kind != DmiOp::Kind::Write || op.reg != RD::kCommand) continue;
717	    const bool is_write = ((op.value >> 16) & 1u) != 0;
718	    if (is_write) continue;
719	    const uint16_t regno = op.value & 0xffffu;
720	    ++reads;
721	    if (regno == hybrid::regno_csr(RD::kCsrMcycle))   ++mcycle_reads;
722	    if (regno == hybrid::regno_csr(RD::kCsrMinstret)) ++minstret_reads;
723	    CHECK(regno < 0x1000u);  // never a GPR (>=0x1000) nor FPR (>=0x1020)
724	  }
725	  CHECK(reads == 2);
726	  CHECK(mcycle_reads == 1);
727	  CHECK(minstret_reads == 1);
728	}
