// #1 (drain block-store): the dual of the resume block-load. Instead of 31/32
// per-register Abstract Command READS, drain sweeps the GPRs/FPRs from the
// regfile INTO the shared scratch page via a PB sd/fsd-sweep (the simulator
// lifts the bytes with read_{gpr,fpr}_from_scratch). Opt-in + fits-gated,
// mirroring the resume side; RecordingBus models no guest RAM, so these assert
// on the DMI traffic (sweep encodings, base seed, no per-register reads) and
// the e2e --verify fixtures prove the values round-trip.
static bool progbuf_has(const std::vector<DmiOp>& ops, uint32_t insn)
{
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write
        && op.reg >= hybrid::kProgbuf0
        && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
        && op.value == insn)
      return true;
  return false;
}

static bool data0_staged(const std::vector<DmiOp>& ops, uint64_t value)
{
  const auto lo = static_cast<uint32_t>(value & 0xffffffffu);
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write && op.reg == RD::kData0 && op.value == lo)
      return true;
  return false;
}

