TEST_CASE("v_regfile_xfer: stage_csr honors caps -- gated CSR skipped, "
          "ALWAYS-gated CSR still transported")
{
  hybrid_state_v1 in{};
  in.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES;
  in.andes.mxstatus = 0xAAAA;  // 0x7C4 ALWAYS-gated: transported even with none()
  in.andes.ucode    = 0xBBBB;  // 0x801 DSP-gated: skipped when the gate is off

  std::vector<uint8_t> ram(static_cast<size_t>(128) * 1024 * 1024);
  hybrid::stage_csr_to_scratch(in, ram, hybrid::AndesCaps::none());

  hybrid_state_v1 out{};
  out.flags = in.flags;
  out.andes.mxstatus = 0x1111;
  out.andes.ucode    = 0x2222;  // sentinel; must survive (not lifted)
  hybrid::read_csr_from_scratch(out, ram, hybrid::AndesCaps::none());

  CHECK(out.andes.mxstatus == 0xAAAAu);  // ALWAYS -> staged + lifted
  CHECK(out.andes.ucode    == 0x2222u);  // DSP gate off -> sentinel intact
}

