// Walk every CSR the sweep transports, in canonical order -- Andes scalars, PMA
// cfg, PMA addr, then M-ext -- gated by the live block flag AND engine caps.
// Invokes fn(slot_index, field_ref) per transported CSR: stage copies
// field->scratch, lift copies scratch->field, both walking THIS identical order
// so slot i agrees on the two sides. State is templated so it binds const
// (stage) and mutable (lift). It applies the same `(flags & FLAG) &&
// caps.supports_csr(addr)` predicate the ResumeDriver restore and StateDrain
// drain build their PB sweep from, so all consumers of the block agree.
template<typename State, typename Fn>
inline void for_each_sweep_csr(State& state, const AndesCaps& caps, Fn&& fn)
{
  std::size_t i = 0;
  if (state.flags & HYBRID_FLAG_ANDES) {
#define X(field, addr, name) \
  if (caps.supports_csr(addr)) { fn(i, state.andes.field); ++i; }
    HYBRID_ANDES_CSR_LIST(X)
#undef X
    for (int p = 0; p < HYBRID_PMA_CFG_NUM; ++p)
      if (caps.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * p)) {
        fn(i, state.andes.pmacfg[p]); ++i;
      }
    for (int p = 0; p < HYBRID_PMA_ADDR_NUM; ++p)
      if (caps.supports_csr(HYBRID_PMA_ADDR0_CSR + p)) {
        fn(i, state.andes.pmaaddr[p]); ++i;
      }
  }
  if (state.flags & HYBRID_FLAG_M_EXT) {
#define X(field, addr, name) \
  if (caps.supports_csr(addr)) { fn(i, state.m_ext.field); ++i; }
    HYBRID_M_EXT_CSR_LIST(X)
#undef X
  }
}

